import csv
import math
import re
from datetime import datetime


DATA_PATH = "/app/dataset/data.csv"

Q4_START = datetime(2025, 10, 1, 0, 0, 0)
Q4_END = datetime(2025, 12, 31, 23, 59, 59)


def parse_event_time(raw):
    raw = raw.strip()
    if raw == "":
        return None
    # format: 2025-10-01T00:00:00Z
    return datetime.strptime(raw, "%Y-%m-%dT%H:%M:%SZ")


def parse_amount(raw):
    s = raw.strip()
    if s == "":
        return float("nan")

    negative = ("CR" in s) or ("(" in s) or (")" in s) or ("-" in s)

    s2 = s.replace("C1", "").replace("C2", "")
    cleaned = re.sub(r"[^0-9,.]", "", s2)

    if cleaned == "":
        return float("nan")

    has_comma = "," in cleaned
    has_dot = "." in cleaned

    if has_comma and has_dot:
        last_comma = cleaned.rfind(",")
        last_dot = cleaned.rfind(".")
        if last_comma > last_dot:
            dec_sep, thou_sep = ",", "."
        else:
            dec_sep, thou_sep = ".", ","
        integer_part = cleaned.replace(thou_sep, "")
        value_str = integer_part.replace(dec_sep, ".")
    elif has_comma or has_dot:
        sep = "," if has_comma else "."
        last_idx = cleaned.rfind(sep)
        digits_after = len(cleaned) - last_idx - 1
        if digits_after == 2:
            integer_part = cleaned[:last_idx].replace(sep, "")
            frac_part = cleaned[last_idx + 1:]
            value_str = integer_part + "." + frac_part
        else:
            value_str = cleaned.replace(sep, "")
    else:
        value_str = cleaned

    try:
        value = float(value_str)
    except ValueError:
        return float("nan")

    if negative and not math.isnan(value):
        value = -abs(value)

    return value


ITEMS_RE = re.compile(r"items=(-?\d+)")
ADJ_RE = re.compile(r"adj=([+-]?\d+(?:\.\d+)?)%")
FEE_RE = re.compile(r"fee=([+-]?\d+(?:\.\d+)?)")
WAIVE_RE = re.compile(r"waive=true", re.IGNORECASE)


def parse_notes(notes):
    items = None
    m = ITEMS_RE.search(notes)
    if m:
        items = int(m.group(1))

    adj_pct = 0.0
    m = ADJ_RE.search(notes)
    if m:
        adj_pct = float(m.group(1)) / 100.0

    fee = 0.0
    m = FEE_RE.search(notes)
    if m:
        fee = float(m.group(1))

    waive = bool(WAIVE_RE.search(notes))

    return items, adj_pct, fee, waive


def compute_net(base_amount, adj_pct, fee, waive):
    if math.isnan(base_amount):
        return float("nan")
    if waive:
        return 0.0
    return base_amount * (1.0 + adj_pct) + fee


def median(values):
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2.0


def answer() -> list[str]:
    with open(DATA_PATH, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        raw_rows = list(reader)

    parsed_rows = []
    for idx, row in enumerate(raw_rows):
        base_amount = parse_amount(row["amount_str"])
        items, adj_pct, fee, waive = parse_notes(row["notes"])
        net = compute_net(base_amount, adj_pct, fee, waive)
        event_time = parse_event_time(row["event_time"])
        parsed_rows.append({
            "idx": idx,
            "record_id": row["record_id"],
            "event_time": event_time,
            "region": row["region"],
            "channel": row["channel"],
            "items": items,
            "net": net,
        })

    best = {}
    for r in parsed_rows:
        et_key = r["event_time"] if r["event_time"] is not None else datetime.min
        net_real = 1 if not math.isnan(r["net"]) else 0
        key = (et_key, net_real)
        rid = r["record_id"]
        if rid not in best or key > best[rid][0]:
            best[rid] = (key, r)

    dedup_rows = [v[1] for v in best.values()]

    filtered = []
    for r in dedup_rows:
        if r["event_time"] is None:
            continue
        if not (Q4_START <= r["event_time"] <= Q4_END):
            continue
        channel = r["channel"].strip().lower()
        if channel == "phone":
            continue
        if math.isnan(r["net"]) or math.isinf(r["net"]):
            continue
        filtered.append(r)

    groups = {}
    for r in filtered:
        month = r["event_time"].strftime("%Y-%m")
        key = (r["region"], month)
        groups.setdefault(key, []).append(r)

    for key, group_rows in groups.items():
        nets = [r["net"] for r in group_rows]
        med = median(nets)
        abs_devs = [abs(n - med) for n in nets]
        mad = median(abs_devs)
        for r in group_rows:
            if mad == 0:
                r["robust_z"] = 0.0
            else:
                r["robust_z"] = 0.6745 * (r["net"] - med) / mad

    for r in filtered:
        items_eff = r["items"] if r["items"] is not None else 1
        items_eff = max(items_eff, 1)
        r["anomaly_score"] = abs(r["robust_z"]) * math.log1p(items_eff)

    ranked = sorted(
        filtered,
        key=lambda r: (
            -r["anomaly_score"],
            -abs(r["robust_z"]),
            -r["event_time"].timestamp(),
            r["record_id"],
        ),
    )

    top10 = [r["record_id"] for r in ranked[:10]]
    return top10


if __name__ == "__main__":
    import json
    result = answer()
    print(result)
    with open("/app/answer.json", "w") as f:
        json.dump(result, f, default=list)

